style.css:
@-moz-document domain("google.com"), domain("www.google.com") {
/* =========================================
   PINKIE GOOGLE ♡
   ========================================= */

:root {
    color-scheme: light !important;
}

/* ===== WHOLE PAGE ===== */

html,
body {
    background: #fff1f5 !important;
    color: #6b4650 !important;
}


/* ===== GOOGLE HOMEPAGE ===== */

body,
.L3eUgb,
.o3j99,
.UcCO7c,
.k1zIA,
.c93Gbe {
    background: #fff1f5 !important;
}

/* Google logo — soft white/pink look */
.lnXdp {
    filter:
        brightness(0)
        saturate(100%)
        invert(92%)
        sepia(14%)
        saturate(578%)
        hue-rotate(295deg)
        brightness(104%) !important;
}


/* ===== HOMEPAGE SEARCH BOX ===== */

.RNNXgb {
    background: #fffaf7 !important;
    border: 2px solid #f3a6bb !important;
    box-shadow:
        0 4px 16px rgba(225, 130, 157, .15) !important;
}

.RNNXgb:hover,
.RNNXgb:focus-within {
    background: #fffdf9 !important;
    box-shadow:
        0 4px 20px rgba(225, 130, 157, .25) !important;
}


/* ===== SEARCH INPUT ===== */

textarea,
input {
    color: #6b4650 !important;
    caret-color: #dc7897 !important;
}

textarea::placeholder,
input::placeholder {
    color: #c79aa6 !important;
}


/* ===== HOMEPAGE BUTTONS ===== */

input[type="submit"],
.gbqfba {
    background: #f6c4d1 !important;
    color: #754a56 !important;
    border: 1px solid #efaabd !important;
    border-radius: 8px !important;
}


/* =========================================
   ACTUAL GOOGLE SEARCH RESULTS
   ========================================= */

.srp,
#main,
#cnt,
#rcnt,
#search,
#center_col,
#appbar,
#top_nav,
#searchform,
.sfbg,
.sfbgg,
.CvDJxb,
.M8OgIe {
    background: #fff1f5 !important;
}


/* ===== RESULTS TOP HEADER ===== */

#searchform,
.sfbg,
.sfbgg,
.CvDJxb {
    background: #ffdce6 !important;
    border-color: #efadbf !important;
}


/* ===== RESULTS SEARCH BAR ===== */

#searchform .RNNXgb,
[role="search"] .RNNXgb {
    background: #fffaf7 !important;
    border: 1.5px solid #efaabd !important;
    box-shadow:
        0 3px 12px rgba(219, 120, 151, .15) !important;
}


/* ===== RESULT CARDS ===== */

.MjjYud,
.g,
.Ww4FFb {
    background: transparent !important;
}


/* ===== RESULT TITLES ===== */

#search h3,
#search h3 span {
    color: #c45f7c !important;
}


/* ===== RESULT TEXT ===== */

#search p,
#search cite {
    color: #74515a !important;
}

#search a {
    color: #b94f70 !important;
}


/* ===== NAVIGATION TABS ===== */

#hdtb,
#hdtb-msb {
    background: #fff1f5 !important;
}

#hdtb a,
#hdtb span {
    color: #9e6474 !important;
}


/* ===== AI OVERVIEW ===== */

[jsname="N760b"] {
    background: #fff7f9 !important;
    color: #6b4650 !important;
    border-color: #efbdca !important;
}


/* ===== KNOWLEDGE PANEL ===== */

.kp-wholepage,
[role="complementary"] {
    background: #fff8f9 !important;
    color: #6b4650 !important;
    border-color: #efbdca !important;
}


/* ===== PEOPLE ALSO ASK / BOXES ===== */

.related-question-pair,
[jsname="Cpkphb"] {
    background: #fff8f9 !important;
    border-color: #efbdca !important;
}


/* ===== DIVIDERS ===== */

hr {
    border-color: #efbdca !important;
}


/* ===== SCROLLBAR ===== */

::-webkit-scrollbar {
    width: 11px;
}

::-webkit-scrollbar-track {
    background: #fff1f5 !important;
}

::-webkit-scrollbar-thumb {
    background: #efadc0 !important;
    border-radius: 20px;
    border: 3px solid #fff1f5;
}

::-webkit-scrollbar-thumb:hover {
    background: #dc819c !important;
}
}
